//! The protocol buffers of Hadoop 3.5.0's IPC layer and HDFS client protocols, generated by
//! prost from the unmodified `.proto` files in `proto/hadoop` (Apache-2.0). The HDFS NameNode,
//! DataNode and client all speak these; nothing else here defines a wire message.
#[allow(clippy::all, clippy::pedantic, dead_code, missing_docs)]
pub mod hadoop {
    pub mod common {
        include!(concat!(env!("OUT_DIR"), "/hadoop.common.rs"));
    }
    pub mod hdfs {
        include!(concat!(env!("OUT_DIR"), "/hadoop.hdfs.rs"));
    }
}

pub use hadoop::common;
pub use hadoop::hdfs;
